// Get all necessary data
const combinationData = $('Loop Over Combinations1').item.json;
const generatedImage = $('Download Runway Result1').item.binary.data;
const runwayResponse = $('Check Generation Status1').item.json;

// Prepare save data
const saveData = {
  combinationId: combinationData.combinationId,
  combinationIndex: combinationData.combinationIndex,
  totalCombinations: combinationData.totalCombinations,
  referenceImageName: combinationData.referenceImageName,
  productName: combinationData.productName,
  imageType: combinationData.imageType || 'gun_to_flag_replacement',
  runwayTaskId: runwayResponse.id,
  generatedAt: new Date().toISOString(),
  fileName: `gun_to_flag_${combinationData.combinationId}_${combinationData.referenceImageName.replace(/[^a-z0-9]/gi, '_')}_${combinationData.productName.replace(/[^a-z0-9]/gi, '_')}.png`
};

// Log progress
console.log(`Saving image ${combinationData.combinationIndex + 1} of ${combinationData.totalCombinations}`);
console.log(`Replaced guns in: ${saveData.referenceImageName} with: ${saveData.productName}`);

// Return with binary
return {
  json: saveData,
  binary: {
    imageToSave: generatedImage
  }
};

